    for r in marked_rows:
        out[r] = [1] * w
    for c in marked_cols:
        for r in range(h):
            out[r][c] = 1
    selected = set()
    for r in marked_rows:
        for seq in (range(w), range(w - 1, -1, -1)):
            for c in seq:
                if grid[r][c] == 2:
                    selected.add((r, c))
                    break
    for c in marked_cols:
        for seq in (range(h), range(h - 1, -1, -1)):
            for r in seq:
                if grid[r][c] == 2:
                    selected.add((r, c))
                    break
    seen = set()
    for r, c in selected:
        if (r, c) in seen:
            continue
        comp = []
        q = deque([(r, c)])
        seen.add((r, c))
        while q:
            y, x = q.popleft()
            comp.append((y, x))
            for dy, dx in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                ny, nx = y + dy, x + dx
                if 0 <= ny < h and 0 <= nx < w and grid[ny][nx] == 2 and (ny, nx) not in seen:
                    seen.add((ny, nx))
                    q.append((ny, nx))
        for y, x in comp:
            out[y][x] = 1
    return out
